def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        current_op = operator[i]
        next_num = operand[i + 1]
        if current_op == '+':
            result += next_num
        elif current_op == '-':
            result -= next_num
        elif current_op == '*':
            result *= next_num
        elif current_op == '//':
            result //= next_num
        elif current_op == '**':
            result **= next_num
        else:
            raise ValueError("Invalid operator")
    return result

